// Helper function to count the number of strings starting with the prefix
function CountFilter(strings: seq<string>, prefix: string): int
    requires strings != null
    requires prefix != null
    ensures CountFilter(strings, prefix) >= 0
{
    var count := 0;
    var i := 0;
    while i < |strings|
        invariant 0 <= i <= |strings|
        invariant count == CountPrefix(strings[0..i], prefix)
    {
        if strings[i].StartsWith(prefix) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

